import csv
import json
from pathlib import Path

DATA = Path(__file__).resolve().parent / "data"

def read_rows(path: Path):
    with path.open(encoding="utf-8-sig", newline="") as f:
        yield from csv.DictReader(f, delimiter=";")

def write_json(path: Path, obj) -> None:
    tmp = path.with_suffix(".tmp")
    tmp.write_text(json.dumps(obj, ensure_ascii=False, indent=2), encoding="utf-8")
    tmp.replace(path)  # swap in the finished file

totals: dict[str, int] = {}
for csv_file in sorted(DATA.glob("*.csv")):
    for row in read_rows(csv_file):
        totals[row["city"]] = totals.get(row["city"], 0) + 1

write_json(DATA / "summary.json", totals)

from dataclasses import dataclass

@dataclass(frozen=True)
class Job:
    title: str
    city: str = ""
    salary: int | None = None

    @classmethod
    def from_dict(cls, d: dict) -> "Job":
        salary = d.get("salary")
        return cls(
            title=d["title"].strip(),
            city=d.get("city", "").strip().title(),
            salary=int(salary) if salary not in (None, "") else None,
        )

