import argparse
import csv
import logging
import sys
from pathlib import Path

log = logging.getLogger("jobtools")

class DataError(Exception):
    """Expected problem with the input data."""

def count_by_city(path: Path) -> dict[str, int]:
    counts: dict[str, int] = {}
    try:
        with path.open(encoding="utf-8", newline="") as f:
            for row in csv.DictReader(f):
                counts[row["city"]] = counts.get(row["city"], 0) + 1
    except FileNotFoundError as err:
        raise DataError(f"input file not found: {path}") from err
    except KeyError as err:
        raise DataError(f"missing column {err} in {path}") from err
    return counts

def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Count job offers per city.")
    parser.add_argument("input", type=Path, help="CSV file with a city column")
    parser.add_argument("--top", type=int, default=5, help="number of cities to show")
    parser.add_argument("-v", "--verbose", action="store_true")
    args = parser.parse_args(argv)
    logging.basicConfig(level=logging.DEBUG if args.verbose else logging.INFO)

    try:
        counts = count_by_city(args.input)
    except DataError as err:
        log.error("%s", err)
        return 1
    for city, n in sorted(counts.items(), key=lambda kv: kv[1], reverse=True)[: args.top]:
        print(f"{city}\t{n}")
    log.debug("%d cities in total", len(counts))
    return 0

if __name__ == "__main__":
    sys.exit(main())

